import gzip
import json
import os
import sys

from sqlalchemy import bindparam, create_engine, text

# SCOPE_INPUT is inserted by the local runner from the pinned decisions.
scope = SCOPE_INPUT[sys.argv[1]]
environment = sys.argv[1]


def encode(value):
    if isinstance(value, dict):
        return {key: encode(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [encode(item) for item in value]
    return value.isoformat() if hasattr(value, "isoformat") else value


def rows(connection, table, where=None, params=None):
    sql = "SELECT * FROM " + table
    if where:
        sql += " WHERE " + where
    query = text(sql + " ORDER BY id")
    if params:
        query = query.bindparams(*(bindparam(key, expanding=True) for key in params))
    return [encode(dict(row)) for row in connection.execute(query, params or {}).mappings()]


engine = create_engine(os.environ["KATRAIN_DATABASE_URL"])
with engine.connect() as connection:
    connection.execute(text("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY"))
    try:
        meta = encode(dict(connection.execute(text(
            "SELECT current_database() AS database, "
            "current_setting('transaction_isolation') AS isolation, "
            "current_setting('transaction_read_only') AS read_only, "
            "txid_current_snapshot()::text AS snapshot, clock_timestamp() AS captured_at"
        )).mappings().one()))
        assert meta["database"] == scope["database"]
        assert meta["isolation"] == "repeatable read" and meta["read_only"] == "on"
        columns = list(connection.execute(text(
            "SELECT column_name FROM information_schema.columns "
            "WHERE table_schema = 'public' AND table_name = 'kifu_albums' ORDER BY ordinal_position"
        )).scalars())
        assert columns == scope["album_columns"] and len(columns) == 26
        candidate_ids = scope["candidate_ids"]
        result = {
            "format": "kifu-event-after-korean-two-next-independent-full-preimage-v1",
            "environment": environment,
            "meta": meta,
            "candidate_ids": candidate_ids,
            "album_columns": columns,
            "albums": rows(connection, "kifu_albums", "id IN :ids", {"ids": candidate_ids}),
            "album_sources": rows(connection, "kifu_album_sources", "album_id IN :ids", {"ids": candidate_ids}),
            "sources": rows(connection, "kifu_sources"),
            "events": rows(connection, "kifu_events"),
            "aliases": rows(connection, "kifu_event_aliases"),
            "editions": rows(connection, "kifu_event_editions"),
            "players": rows(connection, "kifu_players", "id IN :ids", {"ids": scope["player_ids"]}),
        }
        query = text(
            "SELECT id, event_id, event_edition_id FROM kifu_albums WHERE id IN :ids ORDER BY id"
        ).bindparams(bindparam("ids", expanding=True))
        result["existing_hold_event_slots"] = [
            dict(row) for row in connection.execute(query, {"ids": scope["prior_hold_ids"]}).mappings()
        ]
        counts = dict(connection.execute(text(
            "SELECT count(*) AS albums, count(event_id) AS event_links, "
            "count(event_edition_id) AS edition_links, "
            "count(black_player_id) + count(white_player_id) AS player_links FROM kifu_albums"
        )).mappings().one())
        result["statistics"] = {key: counts[key] for key in ("albums", "edition_links", "event_links")}
        result["global_counts"] = {
            "games": counts["albums"], "event_links": counts["event_links"], "player_links": counts["player_links"]
        }
        assert [row["id"] for row in result["albums"]] == candidate_ids
        assert [row["id"] for row in result["players"]] == scope["player_ids"]
        assert [row["id"] for row in result["existing_hold_event_slots"]] == scope["prior_hold_ids"]
        assert all(set(row) == set(columns) for row in result["albums"])
    finally:
        connection.rollback()
engine.dispose()
result["capture_method"] = {
    "database_writes": 0,
    "transaction_end": "ROLLBACK",
    "scope_source": "Pinned event decision and approved top20 player decision intersection only",
    "independent_sql_capture": True,
}
sys.stdout.buffer.write(gzip.compress(
    (json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode(), mtime=0
))
